BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Panther Peptides Command Center</title><style>:root{--bg:#050b13;--panel:#0b1727;--line:#203c59;--text:#f2f7fc;--muted:#8ea8c1;--green:#39d49d;--amber:#f2b84b;--red:#ff7185;--blue:#4b9dff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#17375c 0,#07111f 35%,#040910 100%);color:var(--text);font:15px system-ui,-apple-system,sans-serif;min-height:100vh}.wrap{max-width:1600px;margin:auto;padding:22px}.top,.head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:14px}.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#3f91ff,#53dfc0);display:grid;place-items:center;font-weight:900;color:#06101d}.brand h1,.card h2{margin:0}.brand small,.muted,.notice{color:var(--muted)}.nav,.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #2d4c6c;background:#10223a;color:#eaf4ff;padding:10px 13px;border-radius:11px;font-weight:750;cursor:pointer;text-decoration:none}.btn.green{background:#123c33;border-color:#236d59;color:#c9f8e7}.btn.amber{background:#3b2c10;border-color:#775b20;color:#ffe0a0}.btn.primary{background:#164b88;border-color:#2e79c8}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4;padding:11px 15px;border-radius:13px;margin-bottom:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.metric,.card{background:linear-gradient(180deg,rgba(15,32,53,.98),rgba(9,22,38,.98));border:1px solid var(--line);border-radius:18px}.metric{padding:17px}.metric b{display:block;font-size:27px;margin-top:6px}.metric span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(350px,.72fr);gap:18px}.card{padding:20px}.tablewrap{overflow:auto;border:1px solid #1f3852;border-radius:14px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:12px;border-bottom:1px solid #1d354e;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#91acc6;background:#0a1727}td{color:#e8f1fa}.pill{display:inline-block;border:1px solid #31516f;border-radius:999px;padding:5px 9px;font-size:12px}.pill.available,.pill.released,.pill.approved,.pill.on_file{color:#bdf5df;border-color:#286b59;background:#0d2b24}.pill.quarantine,.pill.hold,.pill.blocked{color:#ffd278;border-color:#76591e;background:#2b210d}.drop{border:1px dashed #3a6082;border-radius:12px;padding:9px;background:#081522}.stack{display:flex;flex-direction:column;gap:12px}.event{padding:12px;border:1px solid #203b57;border-radius:13px;background:#091725}.event b{display:block}.event small{color:var(--muted)}.empty{padding:36px;text-align:center;color:var(--muted)}.jarvisbar{position:sticky;bottom:12px;z-index:20;margin-top:18px;background:rgba(8,20,35,.97);border:1px solid #2b557b;border-radius:18px;padding:12px;box-shadow:0 18px 60px #0008}.jarvisrow{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center}.orb{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#d8fbff,#58d9ff 14%,#177ec7 42%,#0b1830 80%);box-shadow:0 0 22px #4bc9ff66}.jarvisbar input{width:100%;padding:13px 14px;border:1px solid #315779;border-radius:12px;background:#06111f;color:white;font:inherit}.reply{padding:8px 52px 0;color:#c7d9e9;min-height:20px}.login{max-width:520px;margin:10vh auto}.hidden{display:none!important}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.wrap{padding:12px}.jarvisrow{grid-template-columns:auto 1fr}.jarvisrow .btn{grid-column:2}}</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">PP</div><div><h1>Panther Peptides Command Center</h1><small>Jarvis is running business operations in the background · <span id="version"></span></small></div></div><div class="nav"><span id="agentState" class="pill">Jarvis connecting</span><a class="btn" href="/jarvis">Jarvis Console</a><button class="btn" onclick="load()">Refresh</button></div></div><div id="login" class="card login hidden"><h2>Owner Access</h2><p class="notice">Sign in to the Panther Peptides operating dashboard.</p><input id="pw" type="password" placeholder="Owner password" style="width:100%;padding:14px;border-radius:11px;background:#06111f;color:white;border:1px solid #315779"><p><button class="btn primary" onclick="login()">Open Command Center</button></p><div id="loginErr" style="color:var(--red)"></div></div><div id="app"><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Inventory availability and documentation are independently managed.</div><div class="metrics"><div class="metric"><span>Inventory lots</span><b id="lots">—</b></div><div class="metric"><span>Total units</span><b id="units">—</b></div><div class="metric"><span>Held / quarantined</span><b id="quarantine">—</b></div><div class="metric"><span>Available units</span><b id="released">—</b></div><div class="metric"><span>Lots needing documents</span><b id="missing">—</b></div></div><div class="grid"><section class="card"><div class="head"><div><h2>Inventory Control</h2><div class="notice">Receive, document, hold, quarantine and make inventory available from one screen.</div></div><button class="btn" onclick="importLegacy()">Recover legacy inventory</button></div><div class="tablewrap"><table><thead><tr><th>Product</th><th>Lot / SKU</th><th>Qty</th><th>Availability</th><th>Documentation</th><th>Actions</th></tr></thead><tbody id="inventory"></tbody></table></div></section><aside class="stack"><section class="card"><h2>Jarvis Operations</h2><p id="runtime" class="notice">Loading…</p><div id="objectives"></div></section><section class="card"><h2>Business Activity</h2><div id="events"></div></section></aside></div><div class="jarvisbar"><div class="jarvisrow"><div class="orb"></div><input id="ask" placeholder="Ask Jarvis or give him a business instruction…" onkeydown="if(event.key==='Enter')askJarvis()"><button class="btn primary" onclick="askJarvis()">Ask Jarvis</button></div><div id="reply" class="reply">Jarvis is available from the dashboard without leaving your business view.</div></div></div></div><script>const $=id=>document.getElementById(id);let data,history=[];async function api(url,opt={}){const r=await fetch(url,{...opt,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden');throw Error('Owner login required')}if(!r.ok)throw Error(d.detail||d.error||`HTTP ${r.status}`);return d}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pill(s){return `<span class="pill ${esc(String(s).toLowerCase())}">${esc(s)}</span>`}async function login(){try{await api('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('login').classList.add('hidden');$('app').classList.remove('hidden');load()}catch(e){$('loginErr').textContent=e.message}}async function load(){try{let b=await api('/client/bootstrap');$('version').textContent='v'+b.version;data=await api('/business/dashboard');let s=data.summary;$('lots').textContent=s.lots;$('units').textContent=s.units;$('quarantine').textContent=s.quarantined_units;$('released').textContent=s.released_units;$('missing').textContent=s.lots_missing_or_unknown_docs;let rt=data.runtime||{};$('agentState').textContent=rt.worker_alive&&rt.watchdog_alive?'Jarvis online':'Jarvis attention';$('agentState').className='pill '+(rt.worker_alive&&rt.watchdog_alive?'available':'hold');renderInventory();renderOps();renderEvents()}catch(e){if(!String(e.message).includes('Owner login'))console.error(e)}}function renderInventory(){let rows=data.inventory||[];$('inventory').innerHTML=rows.length?rows.map(x=>{let docs=(x.documents||[]).map(d=>`<div>${esc(d.original_name)} ${pill(d.review_status)}</div>`).join('');let controls=x.legacy?'<span class="muted">Import to manage this record.</span>':`<div class="actions"><button class="btn green" onclick="setStatus(${x.id},'available')">Available</button><button class="btn amber" onclick="setStatus(${x.id},'hold')">Hold</button><button class="btn amber" onclick="setStatus(${x.id},'quarantine')">Quarantine</button></div><form class="drop" onsubmit="upload(event,${x.id})"><input type="file" required accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.txt"><button class="btn" type="submit">Upload document</button></form>${docs}`;return `<tr><td><b>${esc(x.product)}</b><br><span class="muted">${esc(x.vial_size||'')}</span></td><td>${esc(x.lot_code||'—')}<br><span class="muted">${esc(x.sku||'')}</span></td><td>${esc(x.quantity)}</td><td>${pill(x.status)}</td><td>${pill(x.coa_status||'unknown')}</td><td>${controls}</td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty">No inventory records visible. Recover legacy inventory to scan the persistent database.</div></td></tr>`}function renderOps(){let o=data.objectives||[];$('runtime').textContent=`${o.filter(x=>['running','queued'].includes(x.state)).length} active / queued · ${o.filter(x=>x.state==='blocked').length} blocked`;$('objectives').innerHTML=o.slice(0,7).map(x=>`<div class="event"><b>#${x.id} ${esc(x.title)}</b><small>${esc(x.state)} · step ${esc(x.step)}/${esc(x.max_steps)}</small></div>`).join('')||'<p class="notice">No active objectives.</p>'}function renderEvents(){$('events').innerHTML=(data.events||[]).slice(0,8).map(e=>`<div class="event"><b>${esc(e.title)}</b><div>${esc(e.detail||'')}</div><small>${esc(e.created_at)}</small></div>`).join('')||'<p class="notice">No business events yet.</p>'}async function importLegacy(){if(!confirm('Recover discoverable inventory from the existing Jarvis database? Existing data will not be deleted.'))return;let d=await api('/business/inventory/import-legacy',{method:'POST'});alert(`Imported ${d.imported} record(s).`);load()}async function upload(ev,id){ev.preventDefault();let f=ev.target.querySelector('input[type=file]').files[0],fd=new FormData();fd.append('file',f);fd.append('kind','coa');let r=await fetch(`/business/inventory/${id}/documents`,{method:'POST',body:fd}),d=await r.json();if(!r.ok)return alert(d.detail||'Upload failed');load()}async function setStatus(id,status){if(!confirm(`Change this lot to ${status}?`))return;try{await api(`/business/inventory/${id}/status`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status})});load()}catch(e){alert(e.message)}}async function askJarvis(){let text=$('ask').value.trim();if(!text)return;$('ask').value='';$('reply').textContent='Jarvis is thinking…';try{let d=await api('/assistant/message',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:text,history:history.slice(-10)})});history.push({role:'user',content:text},{role:'assistant',content:d.reply});$('reply').textContent=d.reply}catch(e){$('reply').textContent='Jarvis error: '+e.message}}load();setInterval(load,12000)</script></body></html>'''